/// <summary>
/// Retrieves the METCustomerTypes record based on the provided RecId.
/// Optionally locks the record for update to prevent concurrent modifications.
/// </summary>
/// <param name="_recId">The unique identifier (RecId) of the METCustomerTypes record to find.</param>
/// <param name="_forUpdate">Specifies whether the record should be locked for update (default is false).</param>
/// <returns>Returns the METCustomerTypes record if found, otherwise returns null.</returns>
static METCustomerTypes find(RefRecId _recId, boolean _forUpdate = false)
{
    METCustomerTypes metCustomerTypes;

    if (_recId)
    {
        metCustomerTypes.selectForUpdate(_forUpdate);

        select firstonly metCustomerTypes
            where metCustomerTypes.RecId == _recId;
    }

    return metCustomerTypes;
}

/// <summary>
/// Checks whether a METCustomerTypes record exists based on the provided RecId.
/// </summary>
/// <param name="_recId">The unique identifier (RecId) of the METCustomerTypes record to check.</param>
/// <returns>Returns true if the record exists, otherwise returns false.</returns>
static boolean exist(RefRecId _recId)
{
    return _recId  &&
       (select firstonly RecId from METCustomerTypes
            where METCustomerTypes.RecId == _recId).RecId != 0;
}
